export default function Chemistry() {
  const [sub, setSub] = useState(null);
  const [loading, setLoading] = useState(true);
  const [lessons, setLessons] = useState([]);
  const [introWatched, setIntroWatched] = useState(false);
  const [initialized, setInitialized] = useState(false);

  const navigate = useNavigate();
  const user = JSON.parse(localStorage.getItem("user")) || null;

  // Check if intro was already watched from backend
  useEffect(() => {
    if (!user || !user.id) {
      console.log("User not logged in - skipping video_progress check");
      return;
    }

    console.log("📡 Checking if intro video is already completed for user:", user.id);

    // Fetch video_progress for intro video (lesson_id=2, video_id=2)
    fetch(`http://localhost:8080/video_progress?user_id=${user.id}&lesson_id=2&video_id=2`)
      .then((res) => {
        console.log("Response status:", res.status);
        if (res.ok) {
          return res.json();
        }
        console.warn("Response not OK, status:", res.status);
        return null;
      })
      .then((data) => {
        console.log("📦 Response data:", data);
        if (data && data.completed === true) {
          console.log("✅ Intro video already completed. Setting introWatched to true");
          setIntroWatched(true);
        } else if (data) {
          console.log("⏳ Intro video not completed. completed:", data.completed);
        } else {
          console.log("⏳ No data returned from endpoint");
        }
      })
      .catch((err) => {
        console.warn("⚠️ Could not fetch video_progress:", err.message);
      });
  }, [user]);

  // Only run once on component mount
  useEffect(() => {
    if (initialized) return; // Prevent re-running

    console.log("🔄 useEffect triggered. introWatched:", introWatched);

    // Skip fetching resources - use fallback
    const found = null; // No resource found
    setSub(found);

    // Create lessons from CHEMISTRY_LESSONS with video data
    const pad = CHEMISTRY_LESSONS.map((lesson) => ({
      id: `local-${lesson.lesson_number}`,
      lesson_number: lesson.lesson_number,
      title: lesson.title,
      status: lesson.lesson_number === 1 ? "unlocked" : "locked",
      videos: lesson.videos
    }));
    console.log("📚 Lessons created:", pad);
    setLessons(pad);
    setLoading(false);
    setInitialized(true); // Mark as initialized to prevent re-runs
  }, [initialized, introWatched]); // Include dependencies

  function markIntroWatched() {
    console.log("🔘 Button clicked - markIntroWatched() called");

    // Send to backend if user is logged in
    if (user && user.id) {
      const videoProgressData = {
        user_id: user.id,
        lesson_id: 2,  // Special ID for intro video (not part of any lesson)
        video_id: 2,   // Special ID for intro video
        watched: true,
        completed: true,
        watch_started_at: new Date().toISOString(),
        completed_at: new Date().toISOString(),
      };

      console.log("📡 Sending to backend /video_progress:", videoProgressData);

      fetch("http://localhost:8080/video_progress", {
        method: "POST",
        headers: { 
          "Content-Type": "application/json",
          "Accept": "application/json"
        },
        body: JSON.stringify(videoProgressData),
      })
        .then((res) => {
          console.log("✅ Response status:", res.status);

          if (res.status === 201 || res.status === 200) {
            return res.json().then(data => {
              console.log("✓ Video progress saved successfully:", data);
              return data;
            }).catch(() => {
              console.log("✓ Saved (no JSON body)");
              return null;
            });
          } else if (res.status === 404) {
            console.error("❌ Endpoint not found (404)");
          } else if (res.status === 500) {
            console.error("❌ Server error (500)");
          }
        })
        .catch((err) => {
          console.error("❌ Network error:", err.message);
        });
    } else {
      console.warn("⚠️ User not logged in - cannot save video progress");
    }

    // Set intro watched state
    setIntroWatched(true);
  }



